function evalRPN(tokens) {
    const stack = [];
    for (const t of tokens) {
        if (t === '+') {
            stack.push(stack.pop() + stack.pop());
        } else if (t === '-') {
            const b = stack.pop(), a = stack.pop();
            stack.push(a - b);
        } else if (t === '*') {
            stack.push(stack.pop() * stack.pop());
        } else if (t === '/') {
            const b = stack.pop(), a = stack.pop();
            stack.push(Math.trunc(a / b));
        } else {
            stack.push(parseInt(t));
        }
    }
    return stack[0];
}
